    [2817]={name="Soft Leather Tunic",quality=2,ilvl=12,sourceType="quest_reward",instructions="Reward from the quest 'Protecting the Herd' - pick it over the other choices. In Dun Morogh.",zone="Dun Morogh",questName="Protecting the Herd",lore="We heard the cries in the middle of the night. Then this morning, sure enough, the herd was missing two rams. That dastardly beast known as Vagash has been preying on our livelihood."},
    [2818]={name="Stretched Leather Trousers",quality=2,ilvl=15,sourceType="quest_reward",instructions="Reward from the quest 'Pyrewood Ambush' - pick it over the other choices. In Silverpine Forest.",zone="Silverpine Forest",questName="Pyrewood Ambush",lore="You got here just in the nick of time! The Pyrewood Council will be returning any moment. Arugal has other matters to tend to in the keep. He uses the Council as mere puppets to keep the mindless minions of Pyrewood under his control."},
