    [3440]={name="Bonecracker",quality=2,ilvl=13,sourceType="quest_reward",instructions="Reward from the quest 'The Family Crypt' - pick it over the other choices. In Tirisfal Glades.",zone="Tirisfal Glades",questName="The Family Crypt",lore="The Agamand Mills area has become a foothold for the Scourge. Their strongest point is the Agamand Family Crypt where their local military leader, a skeleton named Captain Dargol, has headquartered."},
