    [3449]={name="Mystic Shawl",quality=2,ilvl=15,sourceType="quest_reward",instructions="Reward from the quest 'Pyrewood Ambush' - pick it over the other choices. In Silverpine Forest.",zone="Silverpine Forest",questName="Pyrewood Ambush",lore="You got here just in the nick of time! The Pyrewood Council will be returning any moment. Arugal has other matters to tend to in the keep. He uses the Council as mere puppets to keep the mindless minions of Pyrewood under his control."},
    [3451]={name="Nightglow Concoction",quality=2,ilvl=18,sourceType="quest_reward",instructions="Reward from the quest 'A Recipe For Death' - pick it over the other choices. In Silverpine Forest.",zone="Silverpine Forest",questName="A Recipe For Death",lore="According to Berard's Journal the moss from Lake Skulkers and Creepers might prove useful for our quest to brew a new plague. Those beasts dwell on the islands in Lake Lordamere to the east."},
    [3457]={name="Stamped Trousers",quality=2,ilvl=18,sourceType="quest_reward",instructions="Reward from the quest 'Wand to Bethor' - pick it over the other choices. In Silverpine Forest.",zone="Silverpine Forest",questName="Wand to Bethor",lore="Thule once told me that, long ago, he and two colleagues created a magic wand, woven together from the apprentice wands each mage possessed."},
    [3511]={name="Cloak of the People's Militia",quality=2,ilvl=15,sourceType="quest_reward",instructions="Reward from the quest 'Red Leather Bandanas' - pick it over the other choices. In Westfall.",zone="Westfall",questName="Red Leather Bandanas",lore="The Defias Front is constantly shifting. I've been following their movements for quite some time now. On a side note, I've ascertained that many members of the gang can be tracked by the Red Leather Bandanas they wear."},
    [3578]={name="Harvester's Pants",quality=2,ilvl=15,sourceType="quest_reward",instructions="Reward from the quest 'The Killing Fields' - pick it over the other choices. In Westfall.",zone="Westfall",questName="The Killing Fields",lore="Look at what has happened to this place! These lands were once occupied by good farm folk. But the damned thieves have driven them all off. Not me, though!"},
    [3645]={name="Seer's Cuffs",quality=2,ilvl=17,reqLevel=12,sourceType="world_drop",instructions="World drop - drops from 376 creature types around level 11-18. Also found on the auction house."},
    [3647]={name="Bright Bracers",quality=2,ilvl=23,reqLevel=18,sourceType="world_drop",instructions="World drop - drops from 362 creature types around level 18-24. Also found on the auction house."},
    [3741]={name="Stomping Boots",quality=2,ilvl=24,sourceType="quest_reward",instructions="Reward from the quest 'Elixir of Pain' - pick it over the other choices. In Hillsbrad Foothills.",zone="Hillsbrad Foothills",questName="Elixir of Pain",lore="Oh...the flowers are blooming in Hillsbrad and the air is so fresh and brisk. I can't help but to wallow in the misery of it all. I look out my grimy window and long for the day when our New Plague brings this world the death it deserves."},
    [3748]={name="Feline Mantle",quality=3,ilvl=28,reqLevel=23,sourceType="boss_drop",instructions="Drops from Wolf Master Nandos in Shadowfang Keep.",zone="Shadowfang Keep",npc="Wolf Master Nandos"},
