    [9533]={name="Masons Fraternity Ring",quality=3,ilvl=47,sourceType="quest_reward",instructions="Reward from the quest 'Divino-matic Rod' - pick it over the other choices. In Zul'Farrak.",zone="Zul'Farrak",questName="Divino-matic Rod",lore="Sergeant Bly stole from me! He said he'd only borrow it, but he stole my cherished divino-matic rod!! Without that rod how will I know where to dig new water holes??"},
