    [9588]={name="Nogg's Gold Ring",quality=3,ilvl=35,sourceType="quest_reward",instructions="Reward from the quest 'Nogg's Ring Redo'. In Orgrimmar.",zone="Orgrimmar",questName="Nogg's Ring Redo",lore="No, no, no - I'm not all of the sudden saying that the ring is mine."},
    [9603]={name="Gritroot Staff",quality=2,ilvl=10,sourceType="quest_reward",instructions="Reward from the quest 'The Relics of Wakening' - pick it over the other choices. In Teldrassil.",zone="Teldrassil",questName="The Relics of Wakening",lore="Gnarlpine invaders were seen ravaging the Ban'ethil Barrow Den to the west. The slumbering druids will be trapped in the Emerald Dream for eternity, unaware of their fate, unless we help."},
    [9624]={name="Triprunner Dungarees",quality=3,ilvl=37,sourceType="quest_reward",instructions="Reward from the quest 'Rig Wars' - pick it over the other choices. In Gnomeregan.",zone="Gnomeregan",questName="Rig Wars",lore="Gnome technology - two years ago its most common use was as a punch line. Times certainly have changed. Now they've got a new rig built that's better than all our shredder models combined."},
    [9627]={name="Explorer's League Lodestar",quality=2,ilvl=42,sourceType="quest_reward",instructions="Reward from the quest 'The Hidden Chamber' - pick it over the other choices. In Uldaman.",zone="Uldaman",questName="The Hidden Chamber",lore="so you, must find the chamber of Khaz'mul for us! Read my journal, explore the chamber, then report to Prospector Stormpike at the Explorers' League in Ironforge."},
