    [16894]={name="Clear Crystal Rod",quality=2,ilvl=21,sourceType="quest_reward",instructions="Reward from the quest 'Arachnophobia' - pick it over the other choices. In Stonetalon Mountains.",zone="Stonetalon Mountains",questName="Arachnophobia",lore="Warning: Proceed into Sishir Canyon west of here at your own risk. Besseleth and her eight-legged children of the forest have claimed this canyon as their webbed lair."},
    [16897]={name="Stormrage Chestguard",quality=4,ilvl=76,reqLevel=60,sourceType="boss_drop",instructions="Drops from Nefarian.",npc="Nefarian",lore="Deathwing's son, working under Blackrock Mountain to breed the chromatic flight -- dragons carrying the blood of all five. He spent years in Stormwind's court as Lord Victor Nefarius while the work went on."},
    [16898]={name="Stormrage Boots",quality=4,ilvl=76,reqLevel=60,sourceType="boss_drop",instructions="Drops from Broodlord Lashlayer in Blackwing Lair.",zone="Blackwing Lair",npc="Broodlord Lashlayer",lore="Nefarian's lieutenant, posted to hold the only way deeper into the lair."},
    [16899]={name="Stormrage Handguards",quality=4,ilvl=76,reqLevel=60,sourceType="boss_drop",instructions="Drops from Ebonroc in Blackwing Lair.",zone="Blackwing Lair",npc="Ebonroc",lore="One of three drakes guarding Nefarian's inner lair, and the one that heals itself off the wounds it deals."},
    [16900]={name="Stormrage Cover",quality=4,ilvl=76,reqLevel=60,sourceType="boss_drop",instructions="Drops from Onyxia in Onyxia's Lair.",zone="Onyxia's Lair",npc="Onyxia",lore="Deathwing's daughter and Nefarian's sister. She spent years in Stormwind as Lady Katrana Prestor, advising the throne she was working to undermine."},
    [16901]={name="Stormrage Legguards",quality=4,ilvl=76,reqLevel=60,sourceType="boss_drop",instructions="Drops from Ragnaros.",npc="Ragnaros",lore="The Firelord, one of the four Elemental Lords, bound to the Elemental Plane until the Dark Iron dwarves summoned him under Blackrock Mountain. The summoning cracked the mountain open and made the Molten Core."},
    [16902]={name="Stormrage Pauldrons",quality=4,ilvl=76,reqLevel=60,sourceType="boss_drop",instructions="Drops from Chromaggus in Blackwing Lair.",zone="Blackwing Lair",npc="Chromaggus",lore="Nefarian's best result: a two-headed chromatic horror carrying the breath of every dragonflight at once."},
