    [19038]={name="Ring of Subtlety",quality=2,ilvl=48,sourceType="quest_reward",instructions="Reward from the quest 'Zukk'ash Report' - pick it over the other choices. In Feralas.",zone="Feralas",questName="Zukk'ash Report",lore="You've done doubly well in addressing the threat that the Zukk'ash insects pose to Camp Mojache. The threat these things pose is far from over, and I'd like to ask you for one last task on behalf of the Horde."},
