    [19121]={name="Deep Woodlands Cloak",quality=3,ilvl=51,sourceType="quest_reward",instructions="Reward from the quest 'Wanted: Vile Priestess Hexx and Her Minions' - pick it over the other choices. In The Hinterlands.",zone="The Hinterlands",questName="Wanted: Vile Priestess Hexx and Her Minions",lore="By order of Primal Torntusk, Vile Priestess Hexx and her minions are to be brought to justice! A grand reward is offered for any that slay the Vile Priestess Hexx and all of her Aman'zasi elite guard."},
